python3 - <<'PY'
import zipfile
from lxml import etree

p='/root/renewal_playbook_updated.hwpx'
with zipfile.ZipFile(p,'r') as z:
    for n in ['Contents/section0.xml','Contents/section1.xml']:
        root=etree.fromstring(z.read(n))
        ns={'hp': root.nsmap.get('hp') or root.nsmap.get(None)}
        bad=[]
        for pnode in root.xpath('.//hp:p', namespaces=ns):
            t=''.join(pnode.xpath('.//hp:t/text()', namespaces=ns))
            if any(x in t for x in ['Asteron Commerce','한예진','2026-08-12','Priority-24M','renewals-escalation@asteron.example','가격 검토가 끝날 때까지']):
                if pnode.xpath('.//*[local-name()="linesegarray" or local-name()="lineSegArray"]'):
                    bad.append((n, pnode.get('id'), t))
        print(n, 'bad_count', len(bad))
        for b in bad:
            print(' bad', b)
